insert into uat_steps (id, seq, area, title, instructions, expect, closes, expect_fail, fields, active, updated_at) values
  ('S1', 1, 'Setup', 'Install the gateway', 'Run vantage-gateway-<version>.msi on the gateway machine as an administrator. Leave the last screen''s box ticked for S2.', 'It installs without asking for Java. Services shows Vantage Sync Gateway. Start menu has Vantage > Configure Vantage Sync Gateway.', null, null, '[{"key":"version","label":"MSI version"},{"key":"machine","label":"Machine"},{"key":"service","label":"Service present? (yes/no)"},{"key":"shortcut","label":"Start-menu entry present? (yes/no)"}]'::jsonb, true, now()),
  ('S2', 2, 'Setup', 'Give the gateway its application.yml', 'On the installer''s last screen press Finish with the box ticked (or use the Start-menu entry). Pick the prepared application.yml and approve the administrator prompt.', 'The file is copied to C:\ProgramData\Vantage\gateway, the service restarts, and a message says /health answered.', null, null, '[{"key":"message","label":"Message shown"},{"key":"port","label":"Port"},{"key":"backup","label":"Previous file kept as .bak? (yes/no/n.a.)"}]'::jsonb, true, now()),
  ('S3', 3, 'Setup', 'The gateway refuses the wrong file', 'Run Configure Vantage Sync Gateway again and pick a till''s lane.properties, then a copy of application.yml.example.', 'Both are refused by name and nothing changes: the first has no bc:/gateway: sections, the second has the placeholder key.', null, null, '[{"key":"lane_msg","label":"Message for lane.properties"},{"key":"example_msg","label":"Message for the example file"}]'::jsonb, true, now()),
  ('S4', 4, 'Setup', 'The gateway reaches Business Central', 'In PowerShell: Invoke-RestMethod http://localhost:<port>/api/bc/handshake -Headers @{ ''X-Gateway-Api-Key'' = ''<key>'' }', 'The company list comes back and includes ZimChoice Supermarkets.', null, null, '[{"key":"companies","label":"Companies returned"}]'::jsonb, true, now()),
  ('S5', 5, 'Setup', 'ZWG as a POS currency', 'Business Central: Currencies > ZWG > Vantage POS: POS Currency, Lowest Denomination. Currency Exchange Rates: a ZWG rate starting today.', 'POS Currency ticked, Lowest Denomination 0.10, a rate dated today.', 'VPOS-86, VPOS-81', null, '[{"key":"pos_currency","label":"POS Currency"},{"key":"lowest","label":"Lowest Denomination"},{"key":"rate","label":"Rate and starting date"}]'::jsonb, true, now()),
  ('S6', 6, 'Setup', 'VAT posting and ZIMRA tax mappings', 'VAT Posting Setup: the rows for the store''s group (LOCAL) and each item VAT group. Vantage Tax Code Mappings: the LOCAL rows.', 'LOCAL x STD155 is 15.5% and maps to tax id 517. Every VAT group the catalogue uses has a mapping. The letter E is used only for exempt.', 'G7 (VPOS-96)', null, '[{"key":"std155","label":"STD155: VAT % / tax id / letter"},{"key":"zero","label":"ZERO: VAT % / tax id / letter"},{"key":"exempt","label":"EXEMPT: VAT % / tax id / letter"},{"key":"notax","label":"NO TAX: VAT % / tax id / letter"}]'::jsonb, true, now()),
  ('S7', 7, 'Setup', 'Tender types', 'Vantage Tender Types: CASH_USD, CASH_ZWG, the card tender and CUSTOMER. For each: Account No., Overtender Allowed, Change Tender Code, Rounding To, Drawer Opens. CASH_ZWG also: Currency Code ZWG, Foreign Currency ticked, Seek Authorization None.', 'Every tender has an account. Both cash tenders allow overtender (or change can never be given). CASH_ZWG is ZWG drawer cash.', 'VPOS-79, VPOS-80', null, '[{"key":"cash_usd","label":"CASH_USD: account / overtender / rounding"},{"key":"cash_zwg","label":"CASH_ZWG: account / overtender / currency / seek auth."},{"key":"card","label":"Card tender: account / seek auth."},{"key":"customer","label":"CUSTOMER: account"}]'::jsonb, true, now()),
  ('S8', 8, 'Setup', 'Functionality profile', 'Vantage POS Func. Profiles > DEFAULT (or the store''s): Prices Include VAT, Staff PIN Logon, Customer Account Enabled, Dual Pricing Enabled and Secondary Currency Code, Max Drawer Hours, Live Stock Posting, Must Key Price if Zero, Max. Quantity, Max. Price.', 'Values match what the supermarket day needs. Record what you set, including anything left off.', null, null, '[{"key":"incl_vat","label":"Prices Include VAT"},{"key":"account","label":"Customer Account Enabled"},{"key":"dual","label":"Dual Pricing Enabled / Secondary Currency"},{"key":"drawer_hours","label":"Max Drawer Hours"},{"key":"live_stock","label":"Live Stock Posting"},{"key":"key_zero","label":"Must Key Price if Zero"}]'::jsonb, true, now()),
  ('S9', 9, 'Setup', 'Hardware profile', 'Vantage POS HW Profiles > the store''s profile: Receipt Printer Type and Address, Receipt Width, Cash Drawer Port, Open Drawer on Sale, Scale Enabled and Port, EFT Endpoint URL, FDMS Endpoint URL.', 'Open Drawer on Sale ticked. Endpoints filled for what this store uses. No device keys here - they live in each till''s lane.properties.', null, null, '[{"key":"printer","label":"Printer type / address / width"},{"key":"drawer","label":"Drawer port / Open Drawer on Sale"},{"key":"scale","label":"Scale enabled / port"},{"key":"eft","label":"EFT endpoint"},{"key":"fdms","label":"FDMS endpoint"}]'::jsonb, true, now()),
  ('S10', 10, 'Setup', 'The store', 'Vantage Stores > 5001: Location Code, Currency Code (blank = LCY), Func./Hardware/Menu Profile Code, VAT Bus. Posting Group, VAT Registration No., TIN No., Store Dimension Value.', 'VAT Bus. Posting Group is LOCAL (blank sells everything at 0%). TIN and VAT number filled so they print on the slip.', null, 'G20 (VPOS-109): TIN and VAT no. were blank on 24 Sep', '[{"key":"location","label":"Location Code"},{"key":"vat_group","label":"VAT Bus. Posting Group"},{"key":"tin","label":"TIN No."},{"key":"vat_no","label":"VAT Registration No."},{"key":"profiles","label":"Func. / HW / Menu profile"}]'::jsonb, true, now()),
  ('S11', 11, 'Setup', 'A terminal for every tester''s till', 'Store card 5001 > POS Terminals: one line per till. Terminal Type Till; leave the profile codes blank to inherit the store''s; Auto Logoff After (Min.).', 'One terminal per tester''s till, each a distinct number.', null, null, '[{"key":"terminals","label":"Terminal numbers and who uses each"}]'::jsonb, true, now()),
  ('S12', 12, 'Setup', 'Staff permission groups', 'Vantage Staff Perm. Groups: a cashier group and a manager group. Manager: Manager Privileges, Void Line/Transaction, Refund/Return, Price Override, Max. Line and Total Discount %.', 'A cashier group without Manager Privileges and a manager group with it.', 'VPOS-65', null, '[{"key":"cashier","label":"Cashier group: code / max line disc. %"},{"key":"manager","label":"Manager group: code / max line disc. %"}]'::jsonb, true, now()),
  ('S13', 13, 'Setup', 'Staff and PINs', 'Vantage Staff: a record for every tester (Store No. 5001, a group), then Set PIN on each. Then try to give a second person a PIN already in use.', 'Every tester has a PIN. The duplicate is refused, naming who holds it.', 'VPOS-66', null, '[{"key":"staff","label":"Staff IDs created"},{"key":"duplicate","label":"Message for the duplicate PIN"}]'::jsonb, true, now()),
  ('S14', 14, 'Setup', 'Cash movement reasons', 'Vantage Cash Movement Reasons: at least two payout reasons, each with a G/L Account No.', 'Reasons with an account. The till offers only these for a payout.', 'VPOS-33', null, '[{"key":"reasons","label":"Reason codes and G/L accounts"}]'::jsonb, true, now()),
  ('S15', 15, 'Setup', 'Quick keys', 'Vantage POS Menu Profiles > the store''s profile: pages and buttons, including a No Sale and a Reprint function key if the store wants them. Set it on the store card.', 'The F7 grid on the till shows the buttons. Without buttons, No Sale and Reprint of the last receipt are unreachable except from the post-sale screen.', null, null, '[{"key":"profile","label":"Menu profile"},{"key":"buttons","label":"Buttons added"}]'::jsonb, true, now()),
  ('S16', 16, 'Setup', 'Scales and embedded barcodes (if scales are used)', 'Vantage Embedded Barcodes: the store''s label rule. Open Vantage Embedded Barcode Test and decode a real label. Tick Vantage Scale Item on the weighed items.', 'The test page decodes the label to the right item, weight or price. Skip with ''Not run'' if the store has no scales.', 'VPOS-36', null, '[{"key":"rule","label":"Rule code / prefix / length"},{"key":"test_label","label":"Label tested and what it decoded to"},{"key":"scale_items","label":"Items flagged as scale items"}]'::jsonb, true, now()),
  ('S17', 17, 'Setup', 'Posting setup', 'Vantage POS Posting Setup: journal template and batch, Item journal template and batch, Statement Nos. (with room on its No. Series), Rounding Account No., Cash Difference Acc., Max. Rounding Amount, Max. Cash Difference, Local Currency Code, Store Dimension Code, Safe Account No.', 'All filled. Max. Rounding Amount small, so a wrong tender cannot hide in the Rounding Account.', 'VPOS-35', null, '[{"key":"statement_nos","label":"Statement Nos. / last used / ending"},{"key":"rounding","label":"Rounding Account / Max. Rounding Amount"},{"key":"cash_diff","label":"Cash Difference Acc. / Max. Cash Difference"},{"key":"lcy","label":"Local Currency Code"}]'::jsonb, true, now()),
  ('S18', 18, 'Setup', 'Account customers and live stock', 'Customers for the on-account steps: not blocked, with a credit limit. If Live Stock Posting is on: a Job Queue Entry for codeunit 50802. Inventory Setup: Prevent Negative Inventory.', 'At least one account customer with a limit. The job queue entry exists and is Ready (or Live Stock Posting is off).', 'VPOS-27, VPOS-32', null, '[{"key":"customer","label":"Customer no. / credit limit"},{"key":"jobq","label":"Job queue entry (yes/no/n.a.)"},{"key":"neg_inv","label":"Prevent Negative Inventory"}]'::jsonb, true, now()),
  ('S19', 19, 'Setup', 'Install the till', 'Run the till MSI on the tester''s machine. Start Vantage from the Start menu or desktop shortcut (not from a repo folder).', 'It installs and starts. With no settings file yet, it asks for this till''s lane.properties.', null, null, '[{"key":"version","label":"Till version (F9, bottom right)"},{"key":"machine","label":"Machine"},{"key":"asked","label":"Asked for lane.properties? (yes/no)"}]'::jsonb, true, now()),
  ('S20', 20, 'Setup', 'Give the till its lane.properties', 'Answer Yes and pick this till''s lane.properties (store 5001, its terminal, gateway URL and key, FDMS device id and key).', 'It says where it copied the file (.vantage) and the till opens as 5001/<terminal> in the title bar, with no restart.', null, null, '[{"key":"copied_to","label":"Where it was copied"},{"key":"title","label":"Title bar"}]'::jsonb, true, now()),
  ('S21', 21, 'Setup', 'The till refuses the wrong file', 'On a till with no settings (or from Lane setup > Load from a lane.properties file), pick the gateway''s application.yml.', 'Refused by name: it names no gateway and no store. Nothing is written.', null, null, '[{"key":"message","label":"Message shown"}]'::jsonb, true, now()),
  ('S22', 22, 'Setup', 'Lane setup and the logo', 'Sign-in screen > Lane setup > setup code or a manager PIN. Check the values, set Receipt logo and Screen logo to the store''s PNG, Save.', 'It saves (the file path is shown). The header and the basket watermark change to the store''s logo straight away, not TV Sales & Home''s.', 'VPOS-118', null, '[{"key":"saved_to","label":"Saved to"},{"key":"logo","label":"Logo shown after saving"}]'::jsonb, true, now()),
  ('S23', 23, 'Setup', 'First sync', 'Open F9 Status · Sync and wait for the channels to settle.', 'All synced, with the catalogue, prices, staff, tenders and currencies down and nothing failed. Signing in shows every tester''s name.', 'VPOS-85', null, '[{"key":"status","label":"Status headline"},{"key":"channels","label":"Any channel not green"},{"key":"staff","label":"Staff shown on sign-in"}]'::jsonb, true, now()),
  ('S24', 24, 'Setup', 'Printer and drawer', 'F9 > Printers on this till: pick the receipt printer, Print test slip, then Open drawer.', 'The slip prints with the store''s logo and the drawer opens.', null, null, '[{"key":"printer","label":"Printer chosen"},{"key":"slip","label":"Test slip printed? (yes/no)"},{"key":"drawer","label":"Drawer opened? (yes/no)"}]'::jsonb, true, now()),
  ('S25', 25, 'Setup', 'Fiscal device and card terminal ready', 'F9: read the ZIMRA and card lines. Confirm in the FDMS portal that this till''s device has an open fiscal day, and that PayBridge is running for tills with a card terminal.', 'ZIMRA configured with this till''s device id; fiscal day open. Card link up where a terminal is fitted.', 'VPOS-31', null, '[{"key":"device","label":"FDMS device id"},{"key":"day","label":"Fiscal day no. open"},{"key":"card","label":"Card link status"}]'::jsonb, true, now()),
  ('T1', 26, 'Till', 'Sign on and count the float', 'Sign in as a cashier and count the float for each cash currency the till asks for.', 'The till asks for USD and ZWG, and opens a shift.', 'VPOS-33', 'G4 (VPOS-93): asks for ZWG only', '[{"key":"shift","label":"Shift no."},{"key":"asked","label":"Currencies asked for"},{"key":"usd_float","label":"USD float"},{"key":"zwg_float","label":"ZWG float"}]'::jsonb, true, now()),
  ('T2', 27, 'Till', 'Reopen without a Z', 'Close the app and reopen it without cutting a Z.', 'The same shift resumes with the float you counted, not a fresh prompt.', 'VPOS-33', null, '[{"key":"shift","label":"Shift no. after reopening"},{"key":"float","label":"Float shown"}]'::jsonb, true, now()),
  ('T3', 28, 'Till', 'A manager''s own PIN at a supervisor gate', 'As the cashier, trigger a supervisor gate (a line discount over 10%, or End of day). Enter the manager''s PIN.', 'Accepted, and the approval names the manager.', 'VPOS-65', null, '[{"key":"gate","label":"Gate used"},{"key":"approver","label":"Approver shown"}]'::jsonb, true, now()),
  ('T4', 29, 'Till', 'Till price matches the shelf', 'Scan the two items with a known shelf price (note the shelf price and the BC Unit Price first).', 'The till charges exactly the shelf price.', 'U1 (VPOS-112)', null, '[{"key":"item1","label":"Item 1 no."},{"key":"item1_shelf","label":"Item 1 shelf price"},{"key":"item1_till","label":"Item 1 till price (incl. VAT)"},{"key":"item2","label":"Item 2 no."},{"key":"item2_shelf","label":"Item 2 shelf price"},{"key":"item2_till","label":"Item 2 till price (incl. VAT)"}]'::jsonb, true, now()),
  ('T5', 30, 'Till', 'Key an item number; find one by name', 'Key an item number with no barcode. Then press F3 and find an item by part of its name.', 'Both ring.', null, null, '[{"key":"keyed","label":"Item keyed"},{"key":"searched","label":"Item found with F3"}]'::jsonb, true, now()),
  ('T6', 31, 'Till', 'VAT and band per kind of item', 'Ring one standard-rated, one zero-rated, one exempt and one blank-VAT-group item. Look each up in BC''s VAT Posting Setup. After tendering, read the bands on the fiscal slip.', 'Each line''s VAT % equals BC''s setup for that item, and the slip declares the right band.', 'G7 (VPOS-96)', null, '[{"key":"std","label":"Standard: item, BC %, till %, band on slip"},{"key":"zero","label":"Zero-rated: item, BC %, till %, band"},{"key":"exempt","label":"Exempt: item, BC %, till %, band"},{"key":"blank","label":"Blank group: item, BC %, till %, band"}]'::jsonb, true, now()),
  ('T7', 32, 'Till', 'A zero-priced item', 'Ring an item whose price in BC is 0.', 'The till asks for a price or refuses it.', null, 'G11 (VPOS-100): rings at 0.00', '[{"key":"item","label":"Item no."},{"key":"what","label":"What happened"}]'::jsonb, true, now()),
  ('T8', 33, 'Till', 'Void a line, then a whole sale', 'Void one line of a sale and finish it. Then ring another sale and void it whole (F11 → 5).', 'Both voids are recorded and reach BC (check in B1).', null, 'G8 (VPOS-97): a voided sale leaves no record', '[{"key":"line_void_receipt","label":"Receipt with the voided line"},{"key":"void_receipt","label":"Receipt no. of the voided sale"}]'::jsonb, true, now()),
  ('T9', 34, 'Till', 'Park and recall', 'Park a basket (F8), ring and finish another sale, then recall the parked one and finish it.', 'The parked basket comes back whole.', null, null, '[{"key":"parked","label":"Parked receipt no."},{"key":"recalled_total","label":"Total after recall"}]'::jsonb, true, now()),
  ('T10', 35, 'Till', 'Sign out mid-basket', 'A manager rings two items and signs out without finishing. A cashier signs in.', 'The cashier gets a fresh basket under their own name, without the manager''s rights.', null, 'G10 (VPOS-99): keeps the basket and the previous person''s rights', '[{"key":"staff_on_receipt","label":"Staff on the next receipt"},{"key":"basket","label":"What the cashier saw"}]'::jsonb, true, now()),
  ('T11', 36, 'Till', 'Line discount at 10%, then 15%', 'As a cashier, give 10% on a line, then 15% on another.', '10% is taken; 15% asks for a supervisor.', null, null, '[{"key":"ten","label":"Line amount after 10%"},{"key":"fifteen","label":"What 15% did"}]'::jsonb, true, now()),
  ('T12', 37, 'Till', 'USD cash, exact', 'Ring a sale and tender exact USD cash.', 'The sale closes and the drawer opens.', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"gross","label":"Gross"},{"key":"drawer","label":"Drawer opened? (yes/no)"}]'::jsonb, true, now()),
  ('T13', 38, 'Till', 'USD cash with change', 'Ring a sale and hand over more than the total in USD.', 'Change is shown and paid = gross + rounding + change.', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"gross","label":"Gross"},{"key":"paid","label":"Paid"},{"key":"rounding","label":"Rounding"},{"key":"change","label":"Change"}]'::jsonb, true, now()),
  ('T14', 39, 'Till', 'Settle a USD sale in ZWG notes', 'Open tendering on a USD sale. Before pressing, read the Cash ZWG key. Then settle it entirely in ZWG.', 'The key shows the rate and the ZWG balance. The sale closes and the receipt names the tender by its description.', 'VPOS-79, VPOS-80, VPOS-82, VPOS-83', null, '[{"key":"receipt","label":"Receipt no."},{"key":"rate","label":"Rate on the key"},{"key":"usd","label":"USD gross"},{"key":"zwg","label":"ZWG paid"},{"key":"tender_name","label":"Tender name on the receipt"}]'::jsonb, true, now()),
  ('T15', 40, 'Till', 'An unpayable ZWG amount', 'Key a ZWG amount that is not a multiple of 0.10.', 'Refused, naming the denomination.', 'VPOS-81', null, '[{"key":"keyed","label":"Amount keyed"},{"key":"message","label":"Message shown"}]'::jsonb, true, now()),
  ('T16', 41, 'Till', 'Change from the ZWG drawer', 'Overtender a sale in ZWG notes.', 'Change comes back in ZWG, rounded to 0.10, and paid = gross + rounding + change.', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"zwg_paid","label":"ZWG paid"},{"key":"change","label":"Change"},{"key":"rounding","label":"Rounding"}]'::jsonb, true, now()),
  ('T17', 42, 'Till', 'Split USD cash and ZWG notes', 'Settle one sale partly in USD cash and partly in ZWG notes.', 'The sale closes. The fiscal receipt is in the sale''s currency.', null, 'G13 (VPOS-102): fiscalises in ZWG', '[{"key":"receipt","label":"Receipt no."},{"key":"usd_leg","label":"USD leg"},{"key":"zwg_leg","label":"ZWG leg"},{"key":"fiscal_currency","label":"Currency on the fiscal receipt"}]'::jsonb, true, now()),
  ('T18', 43, 'Till', 'Card for an odd total', 'Ring a basket whose total is not a coin multiple and pay by card.', 'The card is charged the exact gross.', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"gross","label":"Gross"},{"key":"charged","label":"Amount on the card slip"}]'::jsonb, true, now()),
  ('T19', 44, 'Till', 'A card decline', 'Force a decline (wrong PIN).', 'The till offers another tender and takes nothing. Do not retry a decline.', null, null, '[{"key":"response","label":"What the till showed"}]'::jsonb, true, now()),
  ('T20', 45, 'Till', 'EcoCash through the terminal', 'Take an EcoCash payment through the card terminal.', 'Declared to ZIMRA as MobileWallet, not Card (read the fiscal record or ask Wyne to).', null, null, '[{"key":"receipt","label":"Receipt no."},{"key":"money_type","label":"Money type declared"}]'::jsonb, true, now()),
  ('T21', 46, 'Till', 'A customer on account', 'F2, attach an account customer, tender on account inside the limit. Then try an amount over the limit.', 'Accepted inside the limit; refused over it with the reason.', 'VPOS-27, VPOS-56', null, '[{"key":"customer","label":"Customer no."},{"key":"receipt","label":"Receipt no."},{"key":"amount","label":"Amount"},{"key":"refusal","label":"Refusal text over the limit"}]'::jsonb, true, now()),
  ('T22', 47, 'Till', 'The fiscal slip, online and offline', 'Read a printed slip and scan its QR with a phone. Then pull the network, make one sale, and plug it back in.', 'Fiscal block, QR that verifies, VAT by band. Offline, the slip says fiscalisation is pending and the stamps arrive once the network is back.', 'VPOS-31', null, '[{"key":"day","label":"Fiscal day"},{"key":"global","label":"Global no."},{"key":"code","label":"Verification code"},{"key":"qr","label":"QR verified? (yes/no)"},{"key":"offline_receipt","label":"Offline receipt no."},{"key":"offline_stamped","label":"Stamped after reconnecting? (yes/no)"}]'::jsonb, true, now()),
  ('T23', 48, 'Till', 'Returns', 'Refund a whole receipt. Return 2 of 6 on a line, then the rest. Return a receipt from another till. Try to refund a sale that has not been fiscalised yet.', 'Credit notes of 20 characters or fewer, summing to the original to the cent. The last one is refused.', 'VPOS-57, VPOS-39', 'G12 (VPOS-101): an unfiscalised sale is not refused', '[{"key":"whole","label":"Whole return: CN no., amount"},{"key":"partials","label":"Partials: CN nos., amounts"},{"key":"other_till","label":"Other till: CN no."},{"key":"unfiscalised","label":"Unfiscalised refund: what happened"}]'::jsonb, true, now()),
  ('T24', 49, 'Till', 'Pickup, safe drop, float add, payout', 'Manager menu → 7 with an empty basket. Do one of each, including a payout with reason Other.', 'A slip each, and the drawer''s expected cash moves by exactly that amount.', 'VPOS-33, VPOS-73', null, '[{"key":"pickup","label":"Pickup amount"},{"key":"drop","label":"Safe drop amount"},{"key":"float_add","label":"Float add amount"},{"key":"payout","label":"Payout amount and reason"}]'::jsonb, true, now()),
  ('T25', 50, 'Till', 'A basket across a Z', 'Open a basket on one till. Cut the Z, open a new shift, then tender the basket.', 'The sale lands on the shift it was tendered on.', 'VPOS-64', null, '[{"key":"receipt","label":"Receipt no."},{"key":"shift","label":"Shift it landed on"}]'::jsonb, true, now()),
  ('T26', 51, 'Till', 'Declare and cut the Z', 'End of day: count each cash drawer and declare, then cut the Z. Compare the screen with the paper.', 'A USD and a ZWG drawer, each with expected, counted and variance. Screen and paper agree.', 'VPOS-35, VPOS-68', 'G3 (VPOS-92): the USD drawer is not counted', '[{"key":"z","label":"Z / shift no."},{"key":"usd","label":"USD: expected / counted / variance"},{"key":"zwg","label":"ZWG: expected / counted / variance"},{"key":"gross","label":"Z gross"},{"key":"vat","label":"VAT by band"}]'::jsonb, true, now()),
  ('B1', 52, 'Business Central', 'Every transaction arrived', 'Count the transaction headers in BC for the shifts tested and compare with the till.', 'One per sale, none missing, voids present.', 'VPOS-31', null, '[{"key":"till_count","label":"Count on the till"},{"key":"bc_count","label":"Count in BC"},{"key":"missing","label":"Missing receipt nos."}]'::jsonb, true, now()),
  ('B2', 53, 'Business Central', 'Fiscal stamps on every header', 'Check the fiscal fields on each transaction header.', 'All present.', 'VPOS-31', null, '[{"key":"missing","label":"Headers without stamps"}]'::jsonb, true, now()),
  ('B3', 54, 'Business Central', 'Cash movements and the Z report arrived', 'Vantage Cash Movements and Vantage Z Reports for the shifts tested.', 'One Z per shift, with a ladder line per currency.', 'VPOS-33, VPOS-35', null, '[{"key":"z","label":"Z report no."},{"key":"currencies","label":"Currencies on the ladder"},{"key":"movements","label":"Cash movements found"}]'::jsonb, true, now()),
  ('B4', 55, 'Business Central', 'Calculate the statement', 'Create and calculate a statement for the store and date.', 'Each tender line in its own currency at the amount taken.', null, 'G1 (VPOS-90): a ZWG-notes tender reads the USD amount as ZWG', '[{"key":"statement","label":"Statement no."},{"key":"zwg_line","label":"ZWG tender line amount"}]'::jsonb, true, now()),
  ('B5', 56, 'Business Central', 'Post the statement', 'Post it.', 'It balances.', 'VPOS-35', null, '[{"key":"revenue","label":"Revenue"},{"key":"vat","label":"Output VAT"},{"key":"tenders","label":"Tenders"},{"key":"cash_diff","label":"Cash difference"}]'::jsonb, true, now()),
  ('B6', 57, 'Business Central', 'Drawer difference per currency', 'Vantage Statement Drawer for the statement.', 'One difference per drawer and currency, matching the Z.', 'VPOS-33', null, '[{"key":"usd","label":"USD difference"},{"key":"zwg","label":"ZWG difference"}]'::jsonb, true, now()),
  ('B7', 58, 'Business Central', 'Item ledger', 'Item Ledger Entries for the day''s sales.', 'Sale quantities posted.', 'VPOS-32', null, '[{"key":"entries","label":"Entries found"}]'::jsonb, true, now()),
  ('B8', 59, 'Business Central', 'Account sale invoice and oldest-first payment', 'Find the invoice for T21''s account sale. Pay part of the customer''s balance and check what it applied to.', 'The sale is its own invoice; the payment applies to the oldest entry first.', 'VPOS-56, VPOS-40', null, '[{"key":"invoice","label":"Invoice no."},{"key":"applied","label":"Entry the payment applied to"}]'::jsonb, true, now()),
  ('B9', 60, 'Business Central', 'Post the same day again', 'Try to post the day again.', 'Nothing moves.', null, null, '[{"key":"before","label":"G/L entries before"},{"key":"after","label":"G/L entries after"}]'::jsonb, true, now()),
  ('B10', 61, 'Business Central', 'Roll the statement back', 'Roll back the posted statement.', 'A net-zero reversal, and the transactions back to Open.', null, null, '[{"key":"doc","label":"Reversal document no."},{"key":"open","label":"Transactions back to Open? (yes/no)"}]'::jsonb, true, now())
